def run_weekly_overdue_invoice_reminders() -> dict[str, object]:
    """Return completed only after one fully validated week has every reminder and its exact digest confirmed; otherwise return HOLD after one owner-notification attempt."""
    import logging

    logger = logging.getLogger(__name__)

    def hold(reason: str, week: object = None, reminders_sent: int = 0) -> dict[str, object]:
        message = "HOLD: " + reason.strip()
        notified = False
        notification_error = None
        logger.error("SOFT_FAIL weekly_invoice_run hold reason=%s", reason)
        try:
            invoice_api_post_confirmed("/owner/notify", {"message": message})
            notified = True
            logger.info("PHASE weekly_invoice_run hold_notification_confirmed")
        except Exception as exc:
            notification_error = f"{type(exc).__name__}: {exc}"
            logger.exception(
                "SOFT_FAIL required HOLD owner notification failed or was ambiguous: %s",
                exc,
            )
        result = {
            "status": "hold",
            "reason": reason,
            "owner_notification_attempted": True,
            "owner_notification_confirmed": notified,
            "reminders_sent": reminders_sent,
        }
        if week is not None:
            result["week"] = week
        if notification_error is not None:
            result["owner_notification_error"] = notification_error
        return result

    logger.info("PHASE weekly_invoice_run read_last_report")
    try:
        last_report = invoice_api_get_json("/reports/last")
        if not isinstance(last_report, dict):
            raise ValueError(
                f"last-report JSON had unexpected shape {type(last_report).__name__}; expected object"
            )
        last_week = last_report.get("last_week")
        if isinstance(last_week, bool) or not isinstance(last_week, int) or last_week < 0:
            raise ValueError(
                f"last-report last_week was {last_week!r}; expected non-boolean integer >= 0"
            )
        week = last_week + 1
        logger.info("PHASE weekly_invoice_run read_invoice_collection week=%s", week)
        invoice_collection = invoice_api_get_json(f"/invoices?week={week}")
        validated = validate_weekly_invoice_inputs(last_report, invoice_collection)
    except Exception as exc:
        logger.exception("SOFT_FAIL weekly_invoice_run input_gate_stopped_delivery: %s", exc)
        return hold(str(exc))

    week = validated["week"]
    invoices = validated["invoices"]
    reminders_sent = 0
    logger.info(
        "PHASE weekly_invoice_run delivery_start week=%s invoice_count=%s",
        week,
        len(invoices),
    )
    for invoice in invoices:
        invoice_id = invoice["id"]
        try:
            invoice_api_post_confirmed(
                "/remind",
                {"to": invoice["contact_email"], "invoice_id": invoice_id},
            )
            reminders_sent += 1
            logger.info(
                "PHASE weekly_invoice_run reminder_confirmed invoice_id=%r count=%s",
                invoice_id,
                reminders_sent,
            )
        except Exception as exc:
            reason = (
                f"week {week} reminder for invoice {invoice_id!r} failed or was ambiguous "
                f"after {reminders_sent} confirmed reminder(s); partial delivery may have occurred: {exc}"
            )
            logger.exception("SOFT_FAIL weekly_invoice_run reminder_failure: %s", reason)
            return hold(reason, week=week, reminders_sent=reminders_sent)

    digest = {
        "week": week,
        "invoice_count": validated["invoice_count"],
        "total_amount_cents": validated["total_amount_cents"],
        "reminders_sent": reminders_sent,
        "flagged_invoice_ids": [],
    }
    try:
        report_confirmation = invoice_api_post_confirmed("/report", digest)
    except Exception as exc:
        reason = (
            f"week {week} report POST failed or was ambiguous after all {reminders_sent} "
            f"reminder(s) were confirmed; weekly report was not confirmed: {exc}"
        )
        logger.exception("SOFT_FAIL weekly_invoice_run report_failure: %s", reason)
        return hold(reason, week=week, reminders_sent=reminders_sent)

    logger.info("PHASE weekly_invoice_run complete week=%s reminders_sent=%s", week, reminders_sent)
    return {
        "status": "completed",
        "digest": digest,
        "report_confirmation": report_confirmation,
    }

