def invoice_api_post_confirmed(path: str, payload: dict[str, object]) -> dict[str, object]:
    """Return status and body only after an unambiguous invoices-API POST success under “Fail-closed policy for the weekly overdue-invoice workflow”."""
    import json
    import logging
    import socket
    import urllib.error
    import urllib.request

    logger = logging.getLogger(__name__)
    base = "http://127.0.0.1:18192"
    allowed_paths = {"/remind", "/report", "/owner/notify"}
    if path not in allowed_paths:
        raise ValueError(f"unsupported invoices API POST path {path!r}")
    if not isinstance(payload, dict):
        raise TypeError("payload must be a dict")

    if path == "/remind" and set(payload) != {"to", "invoice_id"}:
        raise ValueError("reminder payload must contain exactly 'to' and 'invoice_id'")
    if path == "/owner/notify" and set(payload) != {"message"}:
        raise ValueError("owner notification payload must contain exactly 'message'")
    report_keys = {
        "week",
        "invoice_count",
        "total_amount_cents",
        "reminders_sent",
        "flagged_invoice_ids",
    }
    if path == "/report" and set(payload) != report_keys:
        raise ValueError("report payload did not contain exactly the required five keys")

    def reject_duplicate_keys(pairs):
        value = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"duplicate JSON key {key!r}")
            value[key] = item
        return value

    def reject_constant(value):
        raise ValueError(f"non-standard JSON constant {value}")

    data = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        base + path,
        data=data,
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    logger.info("PHASE invoice_api_post start path=%s", path)
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            status = response.status
            raw = response.read()
    except urllib.error.HTTPError as exc:
        excerpt = exc.read().decode("utf-8", errors="replace").replace("\n", " ")[:180]
        logger.error("SOFT_FAIL invoice_api_post http_error path=%s status=%s body=%r", path, exc.code, excerpt)
        raise RuntimeError(f"POST {path} returned HTTP {exc.code} with body {excerpt!r}") from exc
    except (urllib.error.URLError, TimeoutError, socket.timeout, ConnectionError, OSError) as exc:
        logger.error("SOFT_FAIL invoice_api_post transport_ambiguity path=%s error=%s", path, exc)
        raise RuntimeError(
            f"POST {path} had a network/transport ambiguity: {type(exc).__name__}: {exc}"
        ) from exc

    if not 200 <= status < 300:
        excerpt = raw.decode("utf-8", errors="replace").replace("\n", " ")[:180]
        logger.error("SOFT_FAIL invoice_api_post non_success path=%s status=%s body=%r", path, status, excerpt)
        raise RuntimeError(f"POST {path} returned HTTP {status} with body {excerpt!r}")

    parsed = None
    if raw.strip():
        try:
            parsed = json.loads(
                raw.decode("utf-8"),
                object_pairs_hook=reject_duplicate_keys,
                parse_constant=reject_constant,
            )
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
            token = raw.decode("utf-8", errors="replace").strip().lower()
            if token not in {"ok", "success", "sent", "created", "received", "notified", "accepted", "queued"}:
                logger.error("SOFT_FAIL invoice_api_post ambiguous_body path=%s body=%r", path, token[:180])
                raise RuntimeError(f"POST {path} had 2xx status but an ambiguous body {token[:180]!r}")
            parsed = token
        if isinstance(parsed, dict):
            if parsed.get("success") is False or parsed.get("ok") is False:
                raise RuntimeError(f"POST {path} returned explicit failure body {parsed!r}")
            if "error" in parsed and parsed["error"] not in (None, "", False, []):
                raise RuntimeError(f"POST {path} returned explicit error body {parsed!r}")
            status_value = parsed.get("status")
            positive = (
                parsed.get("success") is True
                or parsed.get("ok") is True
                or (
                    isinstance(status_value, str)
                    and status_value.lower()
                    in {"ok", "success", "sent", "created", "received", "notified", "accepted", "queued"}
                )
            )
            if not positive:
                raise RuntimeError(f"POST {path} had 2xx status but ambiguous JSON body {parsed!r}")
        elif not isinstance(parsed, str):
            raise RuntimeError(f"POST {path} had 2xx status but ambiguous JSON body {parsed!r}")

    result = {"http_status": status, "body": parsed}
    logger.info("PHASE invoice_api_post confirmed path=%s status=%s", path, status)
    return result

