def validate_weekly_invoice_inputs(last_report: object, invoice_collection: object) -> dict[str, object]:
    """Return one fully validated week, its invoices, count, and exact EUR-cent total, or raise before delivery."""
    import logging

    logger = logging.getLogger(__name__)
    logger.info("PHASE weekly_invoice_validation start")
    if not isinstance(last_report, dict):
        raise ValueError(
            f"last-report JSON had unexpected shape {type(last_report).__name__}; expected object"
        )
    if "last_week" not in last_report:
        raise ValueError("last-report object was missing required field 'last_week'")
    last_week = last_report["last_week"]
    if isinstance(last_week, bool) or not isinstance(last_week, int) or last_week < 0:
        raise ValueError(
            f"last-report last_week was {last_week!r}; expected non-boolean integer >= 0"
        )
    week = last_week + 1

    if not isinstance(invoice_collection, list):
        raise ValueError(
            f"week {week} invoice collection had unexpected shape "
            f"{type(invoice_collection).__name__}; expected array"
        )

    required = {
        "id",
        "vendor",
        "amount_cents",
        "currency",
        "days_overdue",
        "contact_email",
    }
    seen_ids = set()
    validated = []
    anomalies = []
    for index, invoice in enumerate(invoice_collection):
        location = f"invoice[{index}]"
        if not isinstance(invoice, dict):
            anomalies.append(f"{location} was {type(invoice).__name__}, not object")
            continue
        missing = sorted(required - set(invoice))
        if missing:
            anomalies.append(f"{location} missing fields {missing}")

        invoice_id = invoice.get("id")
        if not isinstance(invoice_id, str) or invoice_id == "":
            anomalies.append(f"{location}.id was not a non-empty string")
        elif invoice_id in seen_ids:
            anomalies.append(f"duplicate invoice id {invoice_id!r}")
        else:
            seen_ids.add(invoice_id)

        if "vendor" in invoice and not isinstance(invoice["vendor"], str):
            anomalies.append(f"{location}.vendor was not a string")
        if "amount_cents" in invoice:
            amount = invoice["amount_cents"]
            if isinstance(amount, bool) or not isinstance(amount, int):
                anomalies.append(f"{location}.amount_cents was not a non-boolean integer")
        if "currency" in invoice:
            currency = invoice["currency"]
            if not isinstance(currency, str) or currency != "EUR":
                anomalies.append(
                    f"{location}.currency was {currency!r}, expected exactly 'EUR'"
                )
        if "days_overdue" in invoice:
            days = invoice["days_overdue"]
            if isinstance(days, bool) or not isinstance(days, int):
                anomalies.append(f"{location}.days_overdue was not a non-boolean integer")
        if "contact_email" in invoice:
            email = invoice["contact_email"]
            if not isinstance(email, str) or email == "":
                anomalies.append(f"{location}.contact_email was not a non-empty string")

        if not missing:
            validated.append(invoice)

    if anomalies:
        preview = "; ".join(anomalies[:4])
        if len(anomalies) > 4:
            preview += f"; plus {len(anomalies) - 4} more anomaly/anomalies"
        logger.error(
            "SOFT_FAIL weekly_invoice_validation week=%s anomalies=%s",
            week,
            len(anomalies),
        )
        raise ValueError(
            f"week {week} invoice validation found {len(anomalies)} anomaly/anomalies: {preview}"
        )

    total = sum(invoice["amount_cents"] for invoice in validated)
    result = {
        "week": week,
        "invoices": validated,
        "invoice_count": len(validated),
        "total_amount_cents": total,
    }
    logger.info(
        "PHASE weekly_invoice_validation complete week=%s invoice_count=%s total_amount_cents=%s",
        week,
        len(validated),
        total,
    )
    return result
